def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n-1)

mod = 998244353

def inverse_modulo(x, mod):
    for i in range(1, mod):
        if (i * i - 1) % mod == 0 and (x * i - 1) % mod == 0:
            return i
    return None

def count_divisions(n, mod):
    fact = factorial(n)
    mod_inv = inverse_modulo(fact, mod)

    total_elem = fact
    target_mod = (n * mod_inv) % mod

    res = [1]
    prev_mod = (factorial(n) - 1) % mod
    for m in range(2, n + 1):
        next_mod = (fact * mod_inv * (-1) ** (1 + m % 2)) % mod
        next_count = (total_elem + 2 * target_mod - prev_mod) % mod
        res.append(next_count)
        prev_mod, total_elem = next_mod, next_count

    return res
