from functools import reduce
from operator import mul
from functools import lru_cache

# ceil(a/b)
def ceil_div(a,b):
    return (a+b-1)//b

mod = 998244353

def solve(n, k):
    # Precompute powers of 2 up to n
    powers = [2**i for i in range(ceil_div(n, 2))]
    mul_powers = [reduce(mul, powers[:(i+1)], 1) for i in range(len(powers))]

    @lru_cache(maxsize=None)
    def knapsack(m, i, j):
        if m < 0 or j >= k:
            return 0
        if m < 2 or i < 0:
            return 1
        if j >= k:
            return 1
        if m < powers[m]: # We can't choose the ball
            return knapsack(m, i-1, j)
        return knapsack(m, i-1, j) + mul_powers[i+1] * knapsack(m-powers[i], i-1, j+1)

    ans = [0] * (k+1)
    ans[0] = 1 # Base case
    for i in range(1, k+1):
        ans[i] = knapsack(i, n-1, 0)

    return ans

