def huffman_encoding(message, q):
    n = len(message)
    encoding = {}
    edges = [[] for _ in range(n)]

    for i in range(1, n):
        for j in range(i+1, n+1):
            if len(message[:i]) == j-i:
                for k in range(i, j+1, 1):
                    if k in encoding:
                        edges[i].append([k, encoding[k]])
                        edges[k].append([i])
                    else:
                        encoding[k] = [i, 0]

            sort_edges(edges[i])

    return back_decode(message, edges, encoding)

def sort_edges(edges):
    edges.sort()

def back_decode(message, edges, encoding):
    deduplicated_message = []
    current_level = len(encoding)

    for i in range(len(message)):
        if i in encoding:
            index_of_encoding = encoding[i]
            if index_of_encoding[1] % 2 == 0:
                encoding[i] = [ind for ind, ignored in edges if current_level - 1 >= ind][-1]
            deduplicated_message.append(message[i] ^ (encoding[i][0] ^ encoding[i][1]))
        else:
            if encoding[current_level-1] == [i]:
                deduplicated_message.append(0)
            else:
                deduplicated_message.append(message[i])

    return deduplicated_message

