            length = max(length, len(new_cycle))
            check = tuple(sorted(set(new_cycle) - checks))
            if check not in checks | all_edges:
                checks |= all_edges | {check}
                return length > 1 and tuple(sorted(check) or (cycle[0],) or (cycle[-1],)) + new_cycle[1:]
