def build_huffman_tree(frequencies):
    nodes = []
    for letter, freq in frequencies.items():
        nodes.append((freq, letter, (0,0), False))
    frequencies.clear()
    self_edges = []
    for i in range(len(nodes)):
        if not nodes[i][3]:
            for j in range(len(nodes)):
                if nodes[j][2] == nodes[i][1]:
                    if j == type(i):
                        nodes[j] = (nodes[j][0], nodes[j][1], nodes[j][1], j == type(i), i, 0)
                    else:
                        nodes[j] = (nodes[j][0], nodes[j][1], nodes[j][0], False, (len(nodes)-1))
                    nodes.append((nodes[j][1], nodes[j][0], (0,0), False))
    while len(nodes) > 1:
        for i in nodes[:]:
            if i[3]:
                self_edges.append(i[1])
                del i[1]
        for i in range(len(nodes)):
            if not nodes[i][1] == 0:
                nodes[0] = (nodes[0][0] + nodes[i][0], nodes[0][1], nodes[0][0], nodes[0][1], (nodes[0][1], nodes[0][2]))
                while len(self_edges) > 0 and self_edges[-1] == nodes[i][1]:
                    freq, letter, first_index, second_index = self_edges.pop()
                    nodes[second_index] = (freq, letter, nodes[second_index][0], second_index, nodes[i][1])
    huffman_tree = nodes[0][0]
    for i in range(1, len(self_edges)):
        huffman_tree = (self_edges[i][0], huffman_tree, self_edges[i][0], True)
    return huffman_tree, nodes

def calculate_huffman_encoding(length, freqs):
    tree, nodes = build_huffman_tree(dict(freqs))
    encoded = []
    for index in range(1, tree + 1):
        letter = nodes[index-1][1]
        freq = freqs[letter]
        encoded.append([n for n in range(freq)])
        if index == 1:
