def find_path(n, graph):
    visited = [False] * (n + 1)
    queue = deque([1])
    path = []
    while queue:
        if visited[1]:
            break
        visited[1] = True
        path.append(1)
        for next_node in graph[1]:
            if not visited[next_node]:
                queue.append(next_node)
    return path

def find_cycles(m, graph, k):
    visited = [False] * (m + 1)
    cycle_count = 0
    cycle_lengths = []
    for i in range(1, m + 1):
        cycle = []
        queue = deque([i])
        current_node = 1
        while not visited[i] and current_node != 1:
            visited[i] = True
            current_node = graph[i][current_node]
            cycle.append(i)
        if cycle:
            if len(cycle) > 3 and len(cycle) % 3 != 0:
                cycle_count += 1
                cycle_lengths.append(len(cycle))
                if cycle_count == k:
                    return cycle_lengths
        else:
            visited[i] = False
    return cycle_lengths

