def cover_points(n, segments):
    # Using PQ to find the closest point to the current line
    pQ = []
    answer = 0
    for A, B, ax, ay in segments:
        for b_x in range(min(ax, B) + 1, max(ax, B) + 1):
            if (ax, ay) != (b_x, ay) and (ax, b_x) != (b_x, ay):
                heappush(pQ, (abs(ax - b_x), max(ax, b_x)))
                if answer + 1 < n and abs(ax - b_x) == n - 1 and (
                        ay, b_x) != (b_x, ay):
                        answer += 1
                while pQ and pQ[0][0] <= abs(ax - b_x):  
                    x, y = heappop(pQ)
                    if abs(ax - y) > n - answer and abs(b_x - y) > n - answer: 
                        answer += 1
    return answer

