def build_cartesian_tree(seq):
    stack = []
    for i in range(len(seq)):
        parent = i
        while stack:
            cur_node = stack.pop()
            if cur_node[1] > i:
                parent = cur_node
            elif cur_node[1] < i:
                break
        if not stack or cur_node[0] > seq[parent]:
            root = parent
            stack.append(root)
        else:
            stack.append((i, seq[parent]))
            stack.append((parent, seq[parent]))
    return root, stack

