from collections import deque, defaultdict

class HuffmanNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def build_huffman_tree(values):
    counts = defaultdict(int)
    for value in values:
        counts[value] += 1

    priority_queue = deque()
    for value, count in counts.items():
        priority_queue.append((count, value))

    while len(priority_queue) > 1:
        count1, value1 = priority_queue.popleft()
        count2, value2 = priority_queue.popleft()
        combined_node = HuffmanNode(value=value1 + value2, count=count1 + count2)
        combined_node.left = HuffmanNode(value=value1)
        combined_node.right = HuffmanNode(value=value2)
        priority_queue.append((combined_node.count, combined_node))

    return priority_queue[0]

def build_huffman_code(root, current_code, codes):
    if root is None:
        return

    if root.value != 0:
        codes[root.value] = current_code

    build_huffman_code(root.left, current_code + '0', codes)
    build_huffman_code(root.right, current_code + '1', codes)

def calculate_huffman_length(bin_str):
    length = 0
    for bit in bin_str:
        length += 1
    return length

class Node:
    def __init__(self, value):
        self.value = value
        self.children = []

    def __repr__(self):
        return str(self.value)

def generate_huffman_tree(S, code):
    heap = []
    for i in range(len(S)):
        heapq.heappush(heap, (S[i][2], Node(S[i][0])))

    while len(heap) > 1:
        f1 = heapq.heappop(heap)
        f2 = heapq.heappop(heap)
        leaf1 = Node('0')
        leaf2 = Node('1')
        leaf1.children = [f1[1], f2[1]]
        leaf2.children = [f1[1], f2[1]]
        heapq.heappush(heap, (f1[0] + f2[0], leaf1))
        heapq.heappush(heap, (f1[0] + f2[0], leaf2))

    root = heapq.heappop(heap)
    for i in range(len(S)):
        S[i] = (root, code[i])

    root_code = ''
    code[root] = root_code
    for child in root.children:
        generate_huffman_tree(S, code)

def find_query_length(root, sub_str, length=None):
    if root.children is None or len(root.children) == 0:
        return length
    if root.value[1] is not sub_str:
        left_length, right_length = find_query_length(root.left, sub_str, length=left_length or '0'), find_query_length(root.right, sub_str, length=right_length or '1')
        return min(left_length, right_length)
    else:
        valid = (sub_str in root.value[2])
        if valid:
            return find_query_length(root.left, sub_str, length=left_length or 0)
        return 0 if length is None else find_query_length(root.right, sub_str, length+1)

