import sys

class SegmentTree:
    def __init__(self, xs=None):
        if xs is not None:
            self.data = sorted(xs)
        else:
            self.data = [0]

    def add(self, point, value):
        point += 1
        while point < len(self.data):
            self.data[point] += value
            point += point & (-point)

    def query(self, st, fl, sl, fr):
        if st > fr:
            return 0
        return self.querysubtree(st, fl) + self.querysubtree(point + 1, fr) + (fl == st)

    def querysubtree(self, point, sl):
        sum = self.data[point]
        point += point & (-point)
        while point > 0:
            sum -= self.data[point]
            point -= point & (-point)
        return sum

