from collections import defaultdict

class RoadNetwork:
    def __init__(self):
        self.graph = defaultdict(list)
        self.dists_from_source = [float('inf')] * (n + 1)  # To keep track of pairs of costs and ward ids

    def add_edge(self, a, b):
        self.graph[a].append(b)
        self.graph[b].append(a)

    def dijkstra(self, source):
        min_dist = [float('inf')] * (n + 1)
        dist_queue = [(0, source)]
        min_dist[source] = 0

        while dist_queue:
            dist, node = dist_queue.pop(0)

            for neighbor in self.graph[node]:
                cost_to_neighbor = min_dist[node] + 1
                if cost_to_neighbor < min_dist[neighbor]:
                    min_dist[neighbor] = cost_to_neighbor
                    dist_queue.append((cost_to_neighbor, neighbor))

        return min_dist

    def __repr__(self):
        return str(self.graph)


def route_min_price(graph, source, target):
    dist = graph.dijkstra(source)
    ward_price = {i: (inf, None) for i in range(1, n + 1)}
    for adjacent in graph[source]:
        j, k = dist[adjacent], dist[source]
        if j < k:
            ward_price[source] = (k, adjacent)
    previous = {v: -1 for v in range(1, n + 1)}
    min_cost = {v: float('inf')}
    min_start = {v: source}

    for i in range(len(ward_price)):
        for v, (cost, u) in ward_price.items():
            u = min_start[u] if u != source else v
            if cost < min_cost[ward_price[(i + u) % (n + 1)]]:
                min_cost[ward_price[(i + u) % (n + 1)]] = cost
                previous[ward_price[(i + u) % (n + 1)]] = u
                min_start[ward_price[(i + u) % (n + 1)]] = v

    result_path = [target]
    prev = target
    if target not in min_start.keys():
        return -1
    while target != source:
        result_path.append(previous[prev])
        prev = source  # Before exiting the loop
    result_path.pop()
    return min(min_cost[target] for target in result_path)


