from collections import defaultdict
from heapq import heappush, heappop

def huffman_encode(words):
    if len(words) == 1:
        return ('0' * len(words)), '1'

    min_heap = []
    for w in words:
        heappush(min_heap, (w, []))

    while len(min_heap) > 1:
        left = heappop(min_heap)
        right = heappop(min_heap)
        for i, _ in left[1]:
            heappush(min_heap, (left[0] + right[0], list(i)))
        heappush(min_heap, (left[0] + right[0], []))

    return min_heap[0][0], ''.join(min_heap[0][1] + '1')

def find_min_encoded_length(words, queries):
    encoded_words, mapping = huffman_encode(words)
    encoded_query = []
    prefix = {}
    for i, word in enumerate(words):
        grouped = defaultdict(list)
        for prev_char in mapping.get(word[:i], []):
            grouped[prev_char].append(mapping.get(prev_char + word[i:i+1], ''))
        for prev_char, sorted_suffixes in grouped.items():
            prefix[prev_char] = list(''.join(sorted_suffixes) + '0')
        encoded_query.append(prefix[word[-1]])

    result = []
    for lo, hi in queries:
        if lo == 1:
            result.append(min(encoded_query[hi-1], key=lambda x: len(x)))
        else:
            length = 1 + len(words[:lo - 1])
            result.append(length + sum(1 for i in prefix if words[i : hi] in prefix[i] or mapping[i + words[i:i+1]] in prefix[i + words[i:i+1]]))
    return result

# Example usage
words = [1, 2, 1, 3, 1, 2, 1]  # Example words
queries = [(1, 7), (1, 3), (3, 5), (2, 4), (4, 4)]  # Example queries
print(find_min_encoded_length(words, queries))
