from collections import defaultdict

def get_primes(index, part_sum, count, prime_map):
    if (index, part_sum, count) in prime_map:
        return prime_map[(index, part_sum, count)]

    if part_sum == 0:
        prime_map[(index, part_sum, count)] = index
        return index

    primes = 0
    for i in range(1, 10):
        if i < part_sum:
            continue
        if ((i + part_sum) % index) == 0:
            primes += get_primes(max(index, i), part_sum - i, count + 1, prime_map)

    prime_map[(index, part_sum, count)] = primes
    return primes

def erase_chars(s, x):
    total_sum = sum(int(c) for c in s)
    if (total_sum, x) in erased_chars:
        return erased_chars[(total_sum, x)]

    count = 0
    valid = False
    for i in range(len(s)):
        part_sum = sum(int(c) for c in s[:i+1])
        if part_sum == x:
            new_chars = erase_chars(s[i+1:], x)
            if new_chars == 0:
                valid = True
                break
            else:
                count += new_chars
        else:
            index = s[i] if i == 0 else None
            prime_map = defaultdict(lambda: 0)
            first_prime = get_primes(index, part_sum, 0, prime_map)
            if first_prime == len(s) and first_prime // x < x - part_sum:
                valid = True
                break
            else:
                count += len(s) - first_prime
    erased_chars[(total_sum, x)] = count if valid else -1
    return count

