        graph[v].append((u, w))

    # A binary heap to store the arrival times with updated times
    arrival_time_heap = [(start_time, i, start_time) for i in range(1, num_speedsters + 1)]
    arrival_time_heap.sort()

    def process_speedster(speedster_id):
        global times
        actual_time_available = start_time
        next_speedster_time = -1
        while arrival_time_heap:
            time, i, last_update_time = heappop(arrival_time_heap)
            if time >= next_speedster_time:
                if time > actual_time_available:
                    times[i] = time
                    break
                else:
                    if times[i] == -1:
                        next_speedster_time = time
            else:
                heappush(arrival_time_heap, (time, i, time))
        return next_speedster_time

    times = [-1] * (num_speedsters + 1)
    arrive_time = 0
    for from_vertex, to_vertex, time_from_start, speed in edges:
        arrive_time += speed
