from collections import defaultdict, deque
from typing import List

def get_next(target, curr):
    return [i for i, color in enumerate(curr[len(target)+1:]) if str(color) == str(target)]

def bfs(start, end):
    q = deque([(start, "")])
    visited = {start: ""}
    while q:
        node, color = q.popleft()
        if node == end:
            return color
        possible_moves = [[i] + [str(o) if o == l else str(o) for o in c] for i, l in enumerate(curr if node != start else []) for c in neighbors.get(str(node), [])]
        for move, color in possible_moves:
            if move == end:
                return color
            if move not in visited:
                q.append((move, color_network[color] + color))
                visited[move] = color_network[color] + color

class MoonMap:
    def __init__(self, n):
        self.n, self.nodes, self.neighbors, self.color_network = n, defaultdict(set), defaultdict(set), {}

    def add_edge(self, u, v, l):
        self.nodes[u], self.nodes[v] = sorted(self.nodes[u] + [u], default=lambda: [0]), sorted(self.nodes[v] + [v], default=lambda: [0])
        for ind in self.nodes[u]:
            curr = self.nodes[ind]
            self.neighbors[ind].add(u) 
            self.neighbors[u].add(ind)
            if l in curr:
                self.color_network[ind] = self.color_network[u]
            else:
                self.color_network[ind] = self.color_network[u] + l
            color_network[self.color_network[ind]] = self.color_network[ind]

    def query(self, u, v, S):
        n = len(self.nodes)
        curr = self.nodes[v]
        color_network = {c: b for b, c in self.color_network.items()} 
        for k in enumerate(S):
            colors = get_next(k, curr)
            if colors:
                curr = self.nodes[colors[0]]
                color_network[colors[1]] = k
        return bfs(u, v)

