def is_connected(grid):
    def neighbors(i, j):
        directions = [(1, 0), (0, 1), (-1, 0), (0, -1)]
        for x, y in directions:
            I = i + x
            J = j + y
            if 0 <= I < n and 0 <= J < m:
                yield (I, J)

    def dfs(i, j, visited):
        if (i, j) in visited:
            return False
        if grid[i][j] == ' ':
            return False
        visited.add((i, j))
        for ni, nj in neighbors(i, j):
            dfs(ni, nj, visited)
        return True

    return all(dfs(i, j, set()) for i in range(n) for j in range(m))

