def min_chars_erase(s, x):
    n = len(s)
    dp = [[float('inf')] * (x + 1) for _ in range(n + 1)]

    for i in range(n):
        dp[i + 1][0] = 0
        for j in range(x + 1):
            if i == 0:
                if j > 0:
                    dp[i + 1][j] = dp[i + 1][j - 1] + abs(int(s[i]) - x) ** 2
                else:
                    dp[i + 1][j] = 0
            else:
                if j <= int(s[i]):
                    dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + abs(int(s[i]) - x) ** 2)
                temp = dp[i][j - int(s[i])]
                if temp != float('inf'):
                    dp[i + 1][j] = min(dp[i + 1][j], temp + abs(int(s[i]) - x) ** 2)
                if j <= int(s[i - 1]):
                    temp = dp[i + 1][j - int(s[i - 1])]
                    if temp != float('inf'):
                        dp[i + 1][j] = min(dp[i + 1][j], temp + abs(int(s[i - 1]) - x) ** 2)

    return dp[n][x] // 2 ** 16
