def count_integer_coords(n, segments):
    used_points = set()
    for segment in segments:
        Ax, Ay, Bx, By = segment
        A_x, A_y = Ax, Ay
        B_x, B_y = Bx, By
        left_points = {(Ax, Ay), (Bx, By)}
        right_points = {(Bx, By), (Ax, Ay)}
        top_points = {(Ax, By), (Bx, Ay)}
        bottom_points = {(Bx, Ay), (Ax, By)}

        if A_y > B_y:
            A_x, B_x = B_x, A_x
            A_y, B_y = B_y, A_y

        if A_x > B_x:
            A_x, B_x = B_x, A_x
            A_y, B_y = B_y, A_y

        for x in range(A_x, B_x + 1):
            for y in range(A_y, B_y + 1):
                point = (x, y)
                if (x, y) in left_points or (x, y) in right_points or (x, y) in top_points or (x, y) in bottom_points:
                    if point not in used_points:
                        used_points.add(point)

    return len(used_points)

