def solve(a, s):
    n = len(a)
    time = 0
    i = s - 1
    current = a[i]

    while True:
        if current > a[(i + 1) % n]:
            if current > a[(i - 1) % n]:
                time += 2
                i += 2
            else:
                time += 1
                i += 1
        else:
            time += 1
            i += 1
        if i == n:
            time += 1
            i = 0
        current = a[i]
        if current == 0:
            break

    return time, i, -(current - 1)
