def find_max_good_segment(test_cases):
    for i in range(test_cases):
        n, k, s = map(int, input().split())
        a = list(map(int, input().split()))

        # Calculate prefix sums
        prefix_sums = [0] * (n + 1)
        for j in range(1, n + 1):
            prefix_sums[j] = prefix_sums[j - 1] + a[j - 1]

        max_length = 0
        for j in range(1, n + 1):
            # Check segments within the range [k, n]
            for k in range(j, n + 1):
                if j * k / (j + k - 1) >= s:
                    break
                segment_sum = prefix_sums[k] - prefix_sums[max(0, k - (j + 2) // 2)] if k > j + 2 // 2 else prefix_sums[k]
                if segment_sum <= s:
                    max_length = max(max_length, k - j + (segment_sum * k) // s)

        print(int(max_length))

